//判断单词是否是变量名
bool IsIdentifier(const string word) {
	if (word.empty()) return false;
	//首字符必须是字母或下划线
	if (!isalpha(word[0]) && word[0] != '_') return false;
	//其余字符必须是字母、数字或下划线
	for (size_t i = 1; i < word.length(); i++) {
		if (!isalnum(word[i]) && word[i] != '_') return false;
	}
	return true;
}

