int wtMatch(const string word) {
	//先匹配保留字与界符
	if (word == "void") return 1;
	if (word == "main") return 2;
	if (word == "int") return 3;
	if (word == "cout") return 4;
	if (word == "return") return 5;
	if (word == "(") return 6;
	if (word == ")") return 7;
	if (word == "{") return 8;
	if (word == "}") return 9;
	if (word == "<<") return 10;
	if (word == ";") return 11;
	if (word == ",") return 12;
	if (word == "=") return 13;
	if (word == "*") return 14;
	if (word == "/") return 15;
	//再判断标识符与数字
	if (IsIdentifier(word)) return 16;
	if (IsNum(word)) return 17;
	return 0;
}

