string findError(const string fileName, const string value) {
	ifstream inFile(fileName);
	string result;
	string line;
	int row = 0;
	//逐行查找value出现的所有位置（列号为find返回的0基下标）
	while (getline(inFile, line)) {
		row++;
		size_t pos = line.find(value);
		while (pos != string::npos) {
			result += "第" + to_string(row) + "行第" + to_string(pos) + "列";
			pos = line.find(value, pos + 1);
		}
	}
	inFile.close();
	return result;
}

