void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
	//按空白字符切分出每条规则字符串
	stringstream ss(text);
	string rule_str;
	while (ss >> rule_str) {
		size_t pos = rule_str.find("::=");
		if (pos == string::npos || pos == 0) continue;
		rule r;
		r.left = rule_str[0];
		//按'|'切分右部各候选式
		string right_str = rule_str.substr(pos + 3);
		size_t start = 0;
		while (true) {
			size_t bar = right_str.find('|', start);
			string part = right_str.substr(start, bar == string::npos ? bar : bar - start);
			r.right.push_back(part);
			right_parts.insert(part);
			if (bar == string::npos) break;
			start = bar + 1;
		}
		rules.push_back(r);
		non_terminal.insert(r.left);
		if (start_symbol == '\0') start_symbol = r.left;
	}
	//终结符：右部中出现且不是'@'、也不是非终结符的字符
	for (const string& part : right_parts) {
		for (char c : part) {
			if (c != '@' && !non_terminal.count(c)) terminal.insert(c);
		}
	}
}

