	//分析栈：自底向上输出（栈顶在最右）
	string analysis;
	while (!analysis_s.empty()) {
		analysis = string(1, analysis_s.top()) + analysis;
		analysis_s.pop();
	}
	//剩余输入串：栈顶先输出
	string input;
	while (!input_s.empty()) {
		input += input_s.top();
		input_s.pop();
